SET NAMES utf8mb4;

-- 1. 修复 poi_category（补充 修车厂 分类，幂等）
INSERT INTO poi_category (category_name,description) SELECT '修车厂','车辆维修保养场' WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1 FROM poi_category WHERE category_name='修车厂') t);

-- 2. 清空 poi 关联业务数据（外键依赖倒序）
DELETE FROM gps_data;
DELETE FROM vehicle_status_log;
DELETE FROM traffic_anomaly;
DELETE FROM dispatch;
DELETE FROM cargo_order;
DELETE FROM driver_route;
DELETE FROM factory_warehouse;
DELETE FROM cargo_vehicle_type_match;
DELETE FROM route;
DELETE FROM cargo;
DELETE FROM vehicle;
DELETE FROM factory;
DELETE FROM warehouse;
DELETE FROM poi;
DELETE FROM simulation_record;

